// Arc Tween — Animation, route: ref
// Source: arc-tween
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';

const TAU = 2 * Math.PI;
const DURATION = 750;
const INTERVAL = 1500;

/** Fractions of a full turn; the arc tweens from each to the next, then loops. */
export type Data = number[];

// The notebook tweens to a fresh Math.random() angle each tick; a fixed cycle
// keeps the chart identical across reloads.
const FRACTIONS: Data = [0.127, 0.62, 0.31, 0.85, 0.47, 0.94, 0.18, 0.73];

const formatPercent = d3.format('.0%');

export default function ArcTween({ data = FRACTIONS, width }: { data?: Data; width: number }) {
  const ref = useRef<SVGSVGElement>(null);
  const height = Math.min(400, Math.round(width * 0.5));

  const arc = useMemo(() => {
    const outerRadius = Math.max(0, height / 2 - 10);
    return d3
      .arc<{ endAngle: number }>()
      .innerRadius(outerRadius * 0.75)
      .outerRadius(outerRadius)
      .startAngle(0);
  }, [height]);

  useEffect(() => {
    if (!ref.current) return;

    const svg = d3.select(ref.current);
    svg.selectAll('*').remove(); // StrictMode runs this effect twice

    svg
      .append('path')
      .datum({ endAngle: TAU })
      .attr('fill', 'var(--line)')
      .attr('d', (d) => arc(d) ?? '');

    const foreground = svg
      .append('path')
      .datum({ endAngle: data[0] * TAU })
      .attr('fill', 'var(--accent)')
      .attr('d', (d) => arc(d) ?? '');

    const label = svg
      .append('text')
      .attr('text-anchor', 'middle')
      .attr('dominant-baseline', 'central')
      .attr('fill', 'var(--text)')
      .attr('font-size', Math.max(10, Math.round(height / 9)))
      .text(formatPercent(data[0]));

    let step = 0;
    const timer = d3.interval(() => {
      const from = data[step % data.length];
      step += 1;
      const to = data[step % data.length];

      foreground
        .transition()
        .duration(DURATION)
        .ease(d3.easeCubicInOut)
        .attrTween('d', (d) => {
          const interpolate = d3.interpolate(d.endAngle, to * TAU);
          // Writing back into the datum keeps an interrupted arc consistent
          // with what is drawn, so the next tween starts from the right angle.
          return (t) => {
            d.endAngle = interpolate(t);
            return arc(d) ?? '';
          };
        });

      label
        .transition()
        .duration(DURATION)
        .ease(d3.easeCubicInOut)
        .textTween(() => {
          const interpolate = d3.interpolate(from, to);
          return (t) => formatPercent(interpolate(t));
        });
    }, INTERVAL);

    return () => {
      timer.stop();
      foreground.interrupt();
      label.interrupt();
      svg.selectAll('*').remove();
    };
  }, [arc, data, height]);

  if (width === 0) return null;

  return (
    <svg
      ref={ref}
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Donut arc tweening its end angle between values"
    />
  );
}
